export const STARTER_SAMPLES: Record<string, Record<string, string>> = {
  "api": {"samples/Note.yml":"# What the assistant and the team keep in mind, per project.\n- title: Colours agreed with the designer\n  project: Website relaunch\n  body: Dark green for buttons and links, warm grey for backgrounds. No pure black anywhere.\n- title: Newsletter goes out on a Tuesday\n  project: Autumn newsletter\n  body: Tuesday mornings get the most opens; send before nine.\n- title: The new office's door code\n  project: Office move\n  body: Ask Marcus; it changes on the first of every month and is not written down here.\n","samples/Project.yml":"# The team's projects.\n- name: Website relaunch\n  description: The new website, from the first sketches to the day it goes live.\n- name: Autumn newsletter\n  description: The October issue for customers, with the new opening hours.\n- name: Office move\n  description: Moving to the new office on the second floor in November.\n","samples/Task.yml":"# Tasks across the projects, in every state, some with a due date.\n- { title: Choose the photos for the front page, project: Website relaunch, status: done, dueDate: 2026-09-26 }\n- { title: Write the texts for the services page, project: Website relaunch, status: doing, dueDate: 2026-10-09, details: \"Three short sections and a line for each price.\" }\n- { title: Check the site on a phone, project: Website relaunch, status: todo, dueDate: 2026-10-14 }\n- { title: Ask Sara for the opening hours, project: Autumn newsletter, status: done }\n- { title: Draft the newsletter, project: Autumn newsletter, status: todo, dueDate: 2026-10-10, details: \"Lead with the new opening hours, then the two autumn offers.\" }\n- { title: Book the movers, project: Office move, status: doing, dueDate: 2026-10-20, details: \"Two quotes so far; the second is cheaper but cannot do a Saturday.\" }\n- { title: Order boxes, project: Office move, status: todo }\n"},
  "barbers": {"samples/Barber.yml":"- { name: Elin Sjöberg, bio: Twenty years of classic cuts; fades and scissor work. }\n- { name: Omar Haddad, bio: Beards and modern styles; trained in Gothenburg. }\n","samples/Service.yml":"- { name: Haircut, summary: A cut and a wash., minutes: 30, price: 32 }\n- { name: Beard trim, summary: Shaped and trimmed with a hot towel., minutes: 20, price: 22 }\n- { name: Haircut and beard, summary: \"Both, in one sitting.\", minutes: 50, price: 48 }\n- { name: Children's haircut, summary: For children under 12., minutes: 20, price: 20 }\n"},
  "booking": {"samples/ClassType.yml":"# The studio's classes, as the starter shows them (docs/spec/v0.1.md, Sample data).\n- name: Foundations\n  summary: The basic postures, one at a time, with time to ask questions. A good first class if you have never done yoga.\n  level: beginner\n  durationMinutes: 60\n- name: Hatha\n  summary: Slow, steady postures held for a few breaths each. You leave stretched, warm and rested.\n  level: allLevels\n  durationMinutes: 75\n- name: Vinyasa\n  summary: Postures linked to the breath in a flowing sequence. Expect to move and to sweat a little.\n  level: allLevels\n  durationMinutes: 60\n- name: Yin\n  summary: Long, quiet holds on the floor that ease the joints and the mind. Bring warm socks.\n  level: allLevels\n  durationMinutes: 75\n- name: Power flow\n  summary: A strong, quick sequence for those who know the basic postures well. Arm balances and inversions included.\n  level: advanced\n  durationMinutes: 60\n","samples/Instructor.yml":"- name: Emma Lindqvist\n  bio: Emma has taught Hatha and Yin for twelve years. Her classes are calm, precise and full of small adjustments.\n  portrait: { file: 0.webp, alt: Emma's class stretching sideways in the bright studio, generated: true }\n- name: Oskar Berg\n  bio: Oskar came to yoga from distance running and teaches Vinyasa and Power flow. He likes a good playlist and a clear count.\n- name: Aino Virtanen\n  bio: Aino teaches Foundations and loves first classes. She makes sure everyone leaves knowing a few postures by name.\n","samples/Post.yml":"- title: Morning classes are back\n  address: morning-classes\n  summary: From October the studio opens at seven on weekdays. Start the day with Vinyasa or Hatha before work.\n  cover: { file: 1.webp, alt: A rolled-up yoga mat and a water bottle on a wooden floor by a window, generated: true }\n  body: |\n    From October the studio opens at **seven** on weekdays.\n\n    - Monday and Wednesday: Hatha with Emma\n    - Tuesday and Thursday: Vinyasa with Oskar\n\n    Booking opens a week ahead, as always.\n  publishedOn: 2026-09-21\n  status: published\n- title: What to bring to your first class\n  address: first-class\n  summary: Comfortable clothes and a bottle of water are all you need. We lend mats, blocks and blankets for free.\n  cover: { file: 0.webp, alt: Three people stretching sideways in a bright room, generated: true }\n  body: |\n    Come ten minutes early so we can show you around.\n\n    Wear something you can move in, and bring water. Mats, blocks and blankets are on the shelf by the door.\n  publishedOn: 2026-09-07\n  status: published\n- title: Summer sessions by the sea\n  address: summer-by-the-sea\n  summary: All of August we met on the shore at Lilla Holmen at sunset. Thank you to everyone who came along.\n  cover: { file: 2.webp, alt: A runner on a path by the sea at sunset, generated: true }\n  body: |\n    Forty evenings, one canceled for rain. We will be back next summer.\n  publishedOn: 2026-08-31\n  status: published\n","samples/Session.yml":"# One week of classes, each listed twice: the seed moves the rows to this week and the next in turn,\n# so both weeks show the whole timetable, at these weekdays and times.\n- { classType: Hatha, instructor: Emma Lindqvist, startsAt: 2026-09-28 08:00, capacity: 12 }\n- { classType: Hatha, instructor: Emma Lindqvist, startsAt: 2026-09-28 08:00, capacity: 12 }\n- { classType: Foundations, instructor: Aino Virtanen, startsAt: 2026-09-28 18:00, capacity: 10 }\n- { classType: Foundations, instructor: Aino Virtanen, startsAt: 2026-09-28 18:00, capacity: 10 }\n- { classType: Vinyasa, instructor: Oskar Berg, startsAt: 2026-09-29 07:00, capacity: 14 }\n- { classType: Vinyasa, instructor: Oskar Berg, startsAt: 2026-09-29 07:00, capacity: 14 }\n- { classType: Yin, instructor: Emma Lindqvist, startsAt: 2026-09-30 19:00, capacity: 12 }\n- { classType: Yin, instructor: Emma Lindqvist, startsAt: 2026-09-30 19:00, capacity: 12 }\n- { classType: Power flow, instructor: Oskar Berg, startsAt: 2026-10-01 17:30, capacity: 10 }\n- { classType: Power flow, instructor: Oskar Berg, startsAt: 2026-10-01 17:30, capacity: 10 }\n- { classType: Hatha, instructor: Aino Virtanen, startsAt: 2026-10-02 12:00, capacity: 12 }\n- { classType: Hatha, instructor: Aino Virtanen, startsAt: 2026-10-02 12:00, capacity: 12 }\n- { classType: Vinyasa, instructor: Oskar Berg, startsAt: 2026-10-03 10:00, capacity: 16 }\n- { classType: Vinyasa, instructor: Oskar Berg, startsAt: 2026-10-03 10:00, capacity: 16 }\n- { classType: Yin, instructor: Emma Lindqvist, startsAt: 2026-10-04 17:00, capacity: 12 }\n- { classType: Yin, instructor: Emma Lindqvist, startsAt: 2026-10-04 17:00, capacity: 12 }\n"},
  "crm": {"samples/Customer.yml":"# The CRM's customers, as the starter shows them (docs/spec/v0.1.md, Sample data).\n- name: Nordic Timber Oy\n  email: orders@nordictimber.example\n  phone: +358 40 123 4567\n  segment: enterprise\n  creditLimit: 50000\n  notes: A sawmill group in Lahti that orders twice a month. Invoices go to their Helsinki office, never to the mill.\n- name: Baltic Freight AB\n  email: info@balticfreight.example\n  phone: +46 8 555 012 34\n  segment: enterprise\n  creditLimit: 25000\n  notes: Runs the night ferries between Stockholm and Turku. Asked for a quote on express shipping in the spring.\n- name: Skerry Software\n  email: hello@skerry.example\n  phone: +358 18 123 45\n  segment: smb\n  creditLimit: 5000\n  notes: A team of six in Mariehamn building booking systems. Prefers email over phone calls.\n- name: Helios Energy\n  email: purchasing@helios.example\n  phone: +47 22 12 34 56\n  segment: enterprise\n  creditLimit: 40000\n  notes: Installs solar parks along the Norwegian coast. New purchasing contact since August; introduce yourself.\n- name: Fjord Analytics\n  email: team@fjordanalytics.example\n  phone: +47 55 12 34 56\n  segment: smb\n  creditLimit: 8000\n  notes: Data consultants in Bergen, recommended to us by Skerry. They pay early and like it noticed.\n- name: Kallio Design\n  email: studio@kallio.example\n  phone: +358 9 123 4567\n  segment: smb\n  creditLimit: 3000\n  notes: A two-person design studio in Helsinki. Needs invoices in English.\n- name: Visby Municipality\n  email: inkop@visby.example\n  phone: +46 498 12 34 56\n  segment: government\n  creditLimit: 60000\n  notes: Buys through a framework agreement that runs to 2027. Every order needs their reference number in the notes.\n- name: Arctic Outdoor Co\n  email: shop@arcticoutdoor.example\n  phone: +46 980 123 45\n  segment: smb\n  creditLimit: 12000\n  notes: An outdoor shop in Kiruna with a busy winter season. Orders double from November to March.\n","samples/Order.yml":"- { number: ORD-1001, customer: Nordic Timber Oy, status: shipped, total: 4820, shippingMethod: standard, placedAt: 2026-09-02 09:15 }\n- { number: ORD-1002, customer: Skerry Software, status: shipped, total: 349, shippingMethod: express, placedAt: 2026-09-05 14:40 }\n- { number: ORD-1003, customer: Helios Energy, status: placed, total: 12600, shippingMethod: standard, placedAt: 2026-09-11 10:05 }\n- { number: ORD-1004, customer: Baltic Freight AB, status: canceled, total: 2300, shippingMethod: express, placedAt: 2026-09-14 16:20 }\n- { number: ORD-1005, customer: Visby Municipality, status: placed, total: 8450, shippingMethod: standard, placedAt: 2026-09-18 08:30 }\n- { number: ORD-1006, customer: Kallio Design, status: draft, total: 85, shippingMethod: standard, placedAt: 2026-09-22 11:00 }\n- { number: ORD-1007, customer: Arctic Outdoor Co, status: placed, total: 3150, shippingMethod: express, placedAt: 2026-09-25 13:45 }\n- { number: ORD-1008, customer: Fjord Analytics, status: draft, total: 960, shippingMethod: standard, placedAt: 2026-09-29 15:10 }\n"},
  "invoicing": {"samples/Client.yml":"# A freelancer's clients, invoices and lines, as the starter shows them (docs/spec/v0.1.md, Sample data).\n- name: Skerry Software\n  email: accounts@skerry.example\n  address: |-\n    Torggatan 4\n    22100 Mariehamn\n    Åland, Finland\n  vatNumber: FI12345678\n- name: Kallio Design\n  email: laskut@kallio.example\n  address: |-\n    Fleminginkatu 12 B\n    00530 Helsinki\n    Finland\n  vatNumber: FI87654321\n- name: Solstice Bakery\n  email: hej@solstice.example\n  address: |-\n    Södra Hamngatan 7\n    41114 Göteborg\n    Sweden\n  vatNumber: SE556677889901\n- name: Fjord Analytics\n  email: invoices@fjordanalytics.example\n  address: |-\n    Strandkaien 20\n    5013 Bergen\n    Norway\n","samples/Invoice.yml":"- { number: 2026-001, client: Skerry Software, issuedOn: 2026-08-03, dueOn: 2026-09-02, status: paid }\n- { number: 2026-002, client: Kallio Design, issuedOn: 2026-08-17, dueOn: 2026-09-16, status: paid }\n- { number: 2026-003, client: Solstice Bakery, issuedOn: 2026-08-31, dueOn: 2026-09-30, status: overdue }\n- { number: 2026-004, client: Skerry Software, issuedOn: 2026-09-14, dueOn: 2026-10-14, status: sent }\n- { number: 2026-005, client: Fjord Analytics, issuedOn: 2026-09-28, dueOn: 2026-10-28, status: sent }\n- { number: 2026-006, client: Kallio Design, issuedOn: 2026-10-01, dueOn: 2026-10-31, status: draft }\n","samples/InvoiceLine.yml":"- { invoice: 2026-001, description: Booking page design, quantity: 16, unitPrice: 85 }\n- { invoice: 2026-001, description: Two rounds of changes, quantity: 4, unitPrice: 85 }\n- { invoice: 2026-002, description: \"Brand guidelines, 24 pages\", quantity: 1, unitPrice: 1400 }\n- { invoice: 2026-003, description: \"Menu photography, half day\", quantity: 1, unitPrice: 450 }\n- { invoice: 2026-003, description: Edited photos, quantity: 30, unitPrice: 8 }\n- { invoice: 2026-004, description: \"Booking page, mobile layout\", quantity: 10, unitPrice: 85 }\n- { invoice: 2026-004, description: Hosting setup, quantity: 1, unitPrice: 120 }\n- { invoice: 2026-005, description: Dashboard workshop, quantity: 1, unitPrice: 900 }\n- { invoice: 2026-005, description: Travel to Bergen, quantity: 1, unitPrice: 210.5 }\n- { invoice: 2026-006, description: Website copy, quantity: 6, unitPrice: 75 }\n"},
  "kiosk": {"samples/Dish.yml":"# The truck's menu as the starter shows it. The pictures are from the Smithable image library\n# (smithable-images, CC0).\n- name: Fish soup\n  description: Salmon, cod and shrimp in a creamy broth with dill, served with bread.\n  price: 14.5\n  section: mains\n  picture: { file: food-soup-b.webp, alt: \"A bowl of soup with bread\", generated: true }\n  diet: none\n  allergens: fish, shellfish, milk, gluten\n- name: Salmon with dill potatoes\n  description: Pan-fried salmon, new potatoes and a dill and lemon sauce.\n  price: 17\n  section: mains\n  picture: { file: food-fish-b.webp, alt: \"A plate of salmon with potatoes and dill\", generated: true }\n  diet: none\n  allergens: fish, milk\n- name: Harbour burger\n  description: Beef burger with cheddar, pickles and fries.\n  price: 15\n  section: mains\n  picture: { file: food-burger.webp, alt: \"A burger with fries on a board\", generated: true }\n  diet: none\n  allergens: gluten, milk, mustard\n- name: Green salad\n  description: Leaves, cucumber, peas and a lemon dressing.\n  price: 9\n  section: starters\n  picture: { file: food-salad-b.webp, alt: \"A bowl of green salad on a wooden table\", generated: true }\n  diet: vegan\n- name: Sourdough and butter\n  description: A slice of the day's sourdough with salted butter.\n  price: 4\n  section: starters\n  picture: { file: food-bread-b.webp, alt: \"A loaf of sourdough bread on a board\", generated: true }\n  diet: vegetarian\n  allergens: gluten, milk\n- name: Cheese board\n  description: Three cheeses from the islands, crackers and fig jam.\n  price: 12\n  section: starters\n  picture: { file: food-cheese-b.webp, alt: \"A board of cheeses and crackers\", generated: true }\n  diet: vegetarian\n  allergens: milk, gluten\n  available: false\n- name: Coffee\n  price: 3.5\n  section: drinks\n  picture: { file: drink-coffee-b.webp, alt: \"A cup of black coffee on a saucer\", generated: true }\n  diet: vegan\n- name: Orange juice\n  description: Freshly pressed.\n  price: 4.5\n  section: drinks\n  picture: { file: drink-juice-b.webp, alt: \"A glass of orange juice by a window\", generated: true }\n  diet: vegan\n- name: Tea\n  price: 3\n  section: drinks\n  picture: { file: drink-tea-b.webp, alt: \"A teapot and a cup of tea\", generated: true }\n  diet: vegan\n- name: Berry cake\n  description: A slice of the day's cake with lingonberries and cream.\n  price: 6\n  section: sweets\n  picture: { file: food-cake-b.webp, alt: \"A slice of berry cake on a plate\", generated: true }\n  diet: vegetarian\n  allergens: gluten, milk, egg\n- name: Cinnamon bun\n  price: 4\n  section: sweets\n  picture: { file: cafe-cinnamon-buns-b.webp, alt: \"A tray of cinnamon buns by a café window\", generated: true }\n  diet: vegetarian\n  allergens: gluten, milk, egg\n","samples/Order.yml":"# Orders across the day's statuses, each with its number, as staff see them on the orders page.\n- { number: 1, name: Lena Berg, phone: \"+358 40 123 4567\", email: lena@archipelago.example, status: collected }\n- { number: 2, name: Mats Holm, phone: \"+358 40 234 5678\", status: collected }\n- { number: 3, name: Aino Laine, phone: \"+358 50 345 6789\", email: aino@example.fi, status: collected, note: \"No onions, please.\" }\n- { number: 4, name: Johan Ek, phone: \"+358 40 456 7890\", status: declined, reason: The cheese board is sold out today. }\n- { number: 5, name: Sara Nyström, phone: \"+358 45 567 8901\", email: sara@harbourfreight.example, status: ready }\n- { number: 6, name: Erik Sund, phone: \"+358 40 678 9012\", status: accepted, note: Extra bread. }\n- { number: 7, name: Maja Lind, phone: \"+358 50 789 0123\", email: maja@example.ax, status: accepted }\n- { number: 8, name: Oskar Fors, phone: \"+358 40 890 1234\", status: new }\n- { number: 9, name: Elin Strand, phone: \"+358 45 901 2345\", email: elin@example.ax, status: new, note: Two forks. }\n- { number: 10, name: Noah Kask, phone: \"+358 40 012 3456\", status: new }\n","samples/OrderLine.yml":"# What each sample order holds, at the price when it was ordered.\n- { order: Lena Berg, dish: Fish soup, quantity: 2, unitPrice: 14.5 }\n- { order: Lena Berg, dish: Coffee, quantity: 2, unitPrice: 3.5 }\n- { order: Mats Holm, dish: Harbour burger, quantity: 1, unitPrice: 15 }\n- { order: Aino Laine, dish: Salmon with dill potatoes, quantity: 1, unitPrice: 17 }\n- { order: Aino Laine, dish: Orange juice, quantity: 1, unitPrice: 4.5 }\n- { order: Johan Ek, dish: Cheese board, quantity: 1, unitPrice: 12 }\n- { order: Sara Nyström, dish: Fish soup, quantity: 1, unitPrice: 14.5 }\n- { order: Sara Nyström, dish: Cinnamon bun, quantity: 2, unitPrice: 4 }\n- { order: Erik Sund, dish: Harbour burger, quantity: 2, unitPrice: 15 }\n- { order: Erik Sund, dish: Sourdough and butter, quantity: 1, unitPrice: 4 }\n- { order: Maja Lind, dish: Green salad, quantity: 1, unitPrice: 9 }\n- { order: Maja Lind, dish: Tea, quantity: 1, unitPrice: 3 }\n- { order: Oskar Fors, dish: Fish soup, quantity: 1, unitPrice: 14.5 }\n- { order: Elin Strand, dish: Harbour burger, quantity: 1, unitPrice: 15 }\n- { order: Elin Strand, dish: Berry cake, quantity: 2, unitPrice: 6 }\n- { order: Noah Kask, dish: Coffee, quantity: 1, unitPrice: 3.5 }\n- { order: Noah Kask, dish: Cinnamon bun, quantity: 1, unitPrice: 4 }\n","samples/Stop.yml":"# Where the truck stands this week.\n- { place: West harbour, day: 2026-10-12, hours: \"11:00-14:00\" }\n- { place: The square, day: 2026-10-13, hours: \"11:00-15:00\" }\n- { place: West harbour, day: 2026-10-14, hours: \"11:00-14:00\" }\n- { place: Sjökvarteret, day: 2026-10-15, hours: \"11:00-16:00\", note: By the boat yard. }\n- { place: West harbour, day: 2026-10-16, hours: \"11:00-20:00\" }\n- { place: The market, day: 2026-10-17, hours: \"10:00-22:00\", note: Autumn market all day. }\n- { place: The square, day: 2026-10-18, hours: \"12:00-16:00\" }\n"},
  "marketplace": {"samples/Item.yml":"# What is for sale as the starter shows it (docs/spec/v0.1.md, Sample data). The photos are from\n# the Smithable image library (smithable-images, CC0); the first of each record is its cover.\n- title: Teak sideboard, 1960s\n  photos:\n    - { file: market-sideboard-1.webp, alt: \"A teak sideboard with sliding doors against a white wall\", generated: true }\n    - { file: market-sideboard-2.webp, alt: \"The corner and wood grain of the teak sideboard\", generated: true }\n  description: Two sliding doors that run smoothly and a shelf inside. A few light marks on top; 160 cm wide.\n  price: 240\n  category: furniture\n  condition: good\n  place: Mariehamn\n- title: Two oak dining chairs\n  photos:\n    - { file: market-chairs-1.webp, alt: \"Two oak dining chairs side by side\", generated: true }\n  description: Solid oak, sturdy and without wobbles. Sold as a pair.\n  price: 60\n  category: furniture\n  condition: good\n  place: Jomala\n- title: Wool armchair\n  photos:\n    - { file: market-armchair-1.webp, alt: \"A gray wool armchair in a living room corner\", generated: true }\n    - { file: market-armchair-2.webp, alt: \"The wool fabric and armrest of the armchair\", generated: true }\n  description: Gray wool with oak legs, no stains or tears. Very comfortable for reading.\n  price: 120\n  category: furniture\n  condition: likeNew\n  place: Mariehamn\n- title: Floor lamp with linen shade\n  photos:\n    - { file: market-lamp-1.webp, alt: \"A brass floor lamp with a linen shade against a wall\", generated: true }\n  description: Brass stand, 150 cm tall, with a warm light. The bulb is included.\n  price: 25\n  category: furniture\n  condition: good\n  place: Lemland\n- title: City bike, seven gears\n  photos:\n    - { file: market-city-bike-1.webp, alt: \"A green city bike with a basket on a gravel drive\", generated: true }\n    - { file: market-city-bike-2.webp, alt: \"The handlebar, bell and basket of the city bike\", generated: true }\n  description: Step-through frame, basket and lights. Serviced this spring.\n  price: 180\n  category: bikes\n  condition: good\n  place: Mariehamn\n- title: Balance bike\n  photos:\n    - { file: market-balance-bike-1.webp, alt: \"A child's wooden balance bike on a lawn\", generated: true }\n  description: Wooden balance bike for ages 2 to 4. Our youngest has outgrown it.\n  price: 30\n  category: kids\n  condition: worn\n  place: Finström\n- title: Road bike, 56 cm frame\n  photos:\n    - { file: market-road-bike-1.webp, alt: \"A gray road bike leaning against a garage wall\", generated: true }\n  description: Aluminum frame, 18 gears and new tires. Ridden two summers.\n  price: 350\n  category: bikes\n  condition: good\n  place: Saltvik\n- title: Laptop, 14 inch\n  photos:\n    - { file: market-laptop-1.webp, alt: \"An open laptop with its charger on a wooden table\", generated: true }\n  description: 16 GB memory, 512 GB disk. Battery lasts about six hours. Charger included.\n  price: 290\n  category: electronics\n  condition: good\n  place: Mariehamn\n- title: Over-ear headphones\n  photos:\n    - { file: market-headphones-1.webp, alt: \"Black over-ear headphones on a wooden table\", generated: true }\n  description: Wireless, with noise canceling. Ear pads replaced last year.\n  price: 85\n  category: electronics\n  condition: likeNew\n  place: Jomala\n- title: Turntable\n  photos:\n    - { file: market-turntable-1.webp, alt: \"A wooden record player on a low shelf beside records\", generated: true }\n    - { file: market-turntable-2.webp, alt: \"The tonearm and a record on the record player\", generated: true }\n  description: Belt drive, new needle. Plays 33 and 45.\n  price: 140\n  category: electronics\n  condition: good\n  place: Mariehamn\n- title: Cross-country skis, 190 cm\n  photos:\n    - { file: market-skis-1.webp, alt: \"Cross-country skis and poles against a red wall in the snow\", generated: true }\n  description: Classic skis with bindings, poles included.\n  price: 70\n  category: sports\n  condition: worn\n  place: Sund\n- title: Sailing dinghy with trailer\n  photos:\n    - { file: market-dinghy-1.webp, alt: \"A white sailing dinghy on a trailer by a granite shore\", generated: true }\n    - { file: market-dinghy-2.webp, alt: \"The sail and tiller inside the dinghy\", generated: true }\n  description: A small dinghy with mast, sail and tiller, on a road trailer. Ready for the summer.\n  price: 1200\n  category: sports\n  condition: good\n  place: Eckerö\n- title: Car roof box\n  photos:\n    - { file: market-roof-box-1.webp, alt: \"A black car roof box on a garage floor\", generated: true }\n  description: 400 litres, fits most roof bars. Key included.\n  price: 110\n  category: other\n  condition: good\n  place: Mariehamn\n- title: Box of children's books\n  photos:\n    - { file: market-books-1.webp, alt: \"A cardboard box of children's picture books on a floor\", generated: true }\n  description: About thirty picture books in Swedish and English.\n  price: 15\n  category: kids\n  condition: worn\n  place: Hammarland\n  available: false\n"},
  "records": {"samples/Item.yml":"# The collection's items, as the starter shows them (docs/spec/v0.1.md, Sample data).\n- name: Stoneware teapot\n  summary: Thrown by hand on Gotland in the 1970s, with a glaze the color of wet sand. It still pours without a drip.\n  kind: favorite\n  addedOn: 2026-09-24\n- name: Bentwood chair\n  summary: One of four chairs from a café that closed in 1962. The seat was recaned last winter.\n  kind: general\n  addedOn: 2026-09-18\n- name: Brass ship's lamp\n  summary: Hung in a fishing boat out of Kökar until the boat was sold. It burns paraffin and smells of it.\n  kind: favorite\n  addedOn: 2026-09-10\n- name: Linen tablecloth\n  summary: Woven in Ostrobothnia with a pattern of small birds. Too long for any table we have.\n  kind: general\n  addedOn: 2026-09-03\n- name: Birch bark basket\n  summary: Plaited from a single strip of bark, the old way. Light enough to carry berries all day.\n  kind: general\n  link: https://en.wikipedia.org/wiki/Birch_bark\n  addedOn: 2026-08-27\n- name: Wall clock\n  summary: A Mora clock in a painted pine case, made around 1840. It needs winding every eight days.\n  kind: favorite\n  link: https://en.wikipedia.org/wiki/Mora_clock\n  addedOn: 2026-08-15\n- name: Enamel coffee pot\n  summary: A blue enamel pot that boiled coffee on a wood stove for forty years. Chipped at the spout, now only for show.\n  kind: archived\n  addedOn: 2026-07-30\n- name: Wool blanket\n  summary: Striped gray and red, from a mill in Jämtland that still makes them. It lives on the reading chair.\n  kind: general\n  addedOn: 2026-07-12\n"},
  "status": {"samples/Component.yml":"# The services the status page reports on (docs/spec/v0.1.md, Sample data).\n- name: Website\n  status: operational\n  description: The public website and the online shop.\n- name: Payments\n  status: degraded\n  description: Card payments at checkout.\n- name: Mobile app\n  status: operational\n  description: The app for iOS and Android.\n","samples/Incident.yml":"# Two incidents: one being watched, one resolved.\n- title: Website unreachable for twenty minutes\n  status: resolved\n  component: Website\n  detectedAt: 2026-09-24 08:40\n  resolvedAt: 2026-09-24 09:01\n  summary: |\n    A certificate renewal failed and browsers refused to connect. The certificate was renewed by\n    hand and the renewal job now alerts the team a week before expiry.\n- title: Card payments slow at checkout\n  status: monitoring\n  component: Payments\n  detectedAt: 2026-10-01 14:05\n  summary: |\n    Card payments took up to a minute to confirm for some customers. The payment provider found a\n    faulty node and moved traffic away from it; we are watching before we call it resolved.\n","samples/IncidentUpdate.yml":"# What the team said while each incident lasted, in order.\n- { incident: Card payments slow at checkout, at: 2026-10-01 14:10, status: investigating, message: We are looking into slow card payments at checkout. }\n- { incident: Card payments slow at checkout, at: 2026-10-01 14:42, status: identified, message: The payment provider found a faulty node and is moving traffic away from it. }\n- { incident: Card payments slow at checkout, at: 2026-10-01 15:20, status: monitoring, message: Payments confirm in seconds again. We are watching for an hour before closing this. }\n- { incident: Website unreachable for twenty minutes, at: 2026-09-24 08:45, status: investigating, message: The website does not load for anyone. We are on it. }\n- { incident: Website unreachable for twenty minutes, at: 2026-09-24 09:01, status: resolved, message: The certificate is renewed and the website is back. }\n","samples/Maintenance.yml":"# Work planned ahead, announced on the status page.\n- title: Database upgrade\n  component: Website\n  startsAt: 2026-10-12 22:00\n  endsAt: 2026-10-12 23:00\n  description: The shop may be slow or show a maintenance page for up to an hour.\n"},
  "support": {"samples/Message.yml":"# Each case's conversation: what the customer wrote after the first mail, and the team's answers.\n- supportCase: Cannot sign in to the booking site\n  sender: agent\n  content: Thanks for writing. We are looking into the sign-in codes now and will get back to you within the hour.\n- supportCase: Cannot sign in to the booking site\n  sender: customer\n  fromEmail: johan@skerrycafe.example\n  content: Thank you. It still happens on my phone, on the laptop it works.\n- supportCase: Invoice sent to the wrong address\n  sender: agent\n  content: We have sent the September invoice to accounts@nordicbuild.example and changed the address for the next ones.\n- supportCase: Invoice sent to the wrong address\n  sender: customer\n  fromEmail: accounts@nordicbuild.example\n  content: Got it, thanks for the quick help.\n","samples/SupportCase.yml":"# Three requests that came in by mail, none taken by an agent yet: two new, one the customer wrote\n# back on after it was answered.\n- subject: Printer out of toner\n  customerEmail: maria@harbourfreight.example\n  status: open\n  priority: 2\n  body: The office printer says it is out of toner. Can you send a new cartridge?\n- subject: Cannot sign in to the booking site\n  customerEmail: johan@skerrycafe.example\n  status: open\n  priority: 4\n  body: Since this morning the sign-in page says my code has expired, every time.\n- subject: Invoice sent to the wrong address\n  customerEmail: accounts@nordicbuild.example\n  status: reopened\n  priority: 3\n  body: Our September invoice went to our old office. Could you send it to accounts@ instead?\n"},
};
